def synch_request(request, timeout \\ 5000) when is_binary(request) or is_map(request) do
  async_request(request, self())

  receive do
    {:response, response} -> {:ok, {:response, response}}
    {:error, error} -> {:error, error}
  after
    timeout -> {:error, :timeout}
  end
end

